INSERT INTO `landing_page_settings` (`id`, `hero_title`, `hero_subtitle`, `video_url`, `stats_cidades`, `stats_atletas`, `stats_jogos`, `stats_papel`, `section_benefits_title`, `created_at`, `updated_at`, `section_benefits_subtitle`, `section_how_it_works_title`, `section_how_it_works_subtitle`, `section_features_title`, `section_sumula_title`, `section_sumula_text`, `footer_about_text`, `contact_email`, `contact_phone`, `social_instagram`, `social_facebook`) VALUES
(1, 'O sistema definitivo para a Gestão Esportiva', 'Digitalize sua Secretaria de Esportes. Elimine o papel, automatize tabelas de campeonatos e conecte a população com um portal exclusivo da sua cidade.', NULL, '40+', '150k', '12k', 'Zero', 'A evolução da sua Secretaria', '2026-03-17 07:37:04', '2026-04-23 15:49:52', 'Chega de perder noites organizando chaves e recebendo fichas de papel rasgadas. Eleve o nível do esporte na sua cidade.', 'Como transformar sua Secretaria em 3 passos', NULL, 'Recursos pensados para o esporte público', 'Aposente o papel com a Súmula Eletrônica', 'Árbitros e mesários preenchem tudo pelo celular ou tablet na beira da quadra. Gols, cartões e substituições são registrados em tempo real, atualizando automaticamente artilharia e tabelas no portal.', 'Ajudando municípios brasileiros a transformar a gestão esportiva através da tecnologia, promovendo transparência e inclusão social.', NULL, '86994675256', NULL, NULL);
