INSERT INTO `noticias` (`id`, `prefeitura_id`, `autor_id`, `categoria_id`, `titulo`, `slug`, `conteudo`, `meta_description`, `imagem_capa`, `video_principal`, `galeria`, `carrossel`, `publicado`, `destaque`, `publicado_em`, `visualizacoes`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 2, 2, 1, 'Secretaria de Esportes participa do 10º Encontro dos Servidores Públicos e realiza abertura do calendário esportivo em São Francisco do Maranhão', 'secretaria-de-esportes-participa-do-10o-encontro-dos-servidores-publicos-e-realiza-abertura-do-calendario-esportivo-em-sao-francisco-do-maranhao', '{\"time\":1773750428812,\"blocks\":[{\"id\":\"npeu784jxU\",\"type\":\"paragraph\",\"data\":{\"text\":\"A Secretaria Municipal de Esportes marcou presença no&nbsp;10º Encontro dos Servidores Públicos do município de São Francisco do Maranhão, promovendo ações voltadas ao incentivo e à valorização da prática esportiva.\"}},{\"id\":\"Bn1rG7lxhn\",\"type\":\"paragraph\",\"data\":{\"text\":\"Durante a programação do evento, foram distribuídos&nbsp;materiais esportivos para equipes da sede do município e também da zona rural, fortalecendo o apoio ao esporte amador e incentivando a participação da população nas atividades esportivas.\"}},{\"id\":\"gp7C5HGk7y\",\"type\":\"carousel\",\"data\":{\"type\":\"carousel\"}},{\"id\":\"HFy8N5wcfT\",\"type\":\"paragraph\",\"data\":{\"text\":\"Na ocasião, também foi realizada a&nbsp;abertura oficial do calendário esportivo municipal, que contará com diversas competições ao longo do ano, envolvendo atletas e comunidades de diferentes regiões do município.\"}},{\"id\":\"s_gt2MEhXC\",\"type\":\"paragraph\",\"data\":{\"text\":\"A iniciativa reforça o compromisso da gestão municipal com o desenvolvimento do esporte, contando com o apoio do&nbsp;prefeito Francisco do Posto&nbsp;e do líder&nbsp;Adelbarto Santos, que têm incentivado ações voltadas ao fortalecimento do esporte no município.\"}},{\"id\":\"eKw7W4mvWZ\",\"type\":\"paragraph\",\"data\":{\"text\":\"De acordo com o secretário municipal de Esportes,&nbsp;José Borges, a população poderá acompanhar todas as atividades esportivas pelos canais oficiais da Secretaria.\"}},{\"id\":\"lwatcXAEg-\",\"type\":\"quote\",\"data\":{\"text\":\"“Estamos iniciando oficialmente o nosso calendário esportivo e, a partir desta segunda-feira, todas as competições e eventos serão divulgados aqui no portal e também nas redes sociais da Secretaria. Nosso objetivo é manter a população informada e incentivar cada vez mais a participação no esporte em nosso município.”\",\"caption\":\"destacou o secretário José Borges.\",\"alignment\":\"left\"}},{\"id\":\"fPFIXji10b\",\"type\":\"paragraph\",\"data\":{\"text\":\"A Secretaria Municipal de Esportes segue trabalhando para estimular a prática esportiva em São Francisco do Maranhão, reconhecendo o esporte como uma importante ferramenta de saúde, lazer e integração social.\"}}],\"version\":\"2.31.3\"}', NULL, 'tenants/2/noticias/Veq8sv1nLuiO04p4YR7TPlE7w8ILDALcMjgnn4Ba.jpg', NULL, NULL, '[\"tenants/2/noticias/carrossel/vfqKMQA7aG5bOv4ZqkGNF6D5Zgl2SqJPHhGtjZSN.jpg\", \"tenants/2/noticias/carrossel/IsZea8gvfCWtsLQXcZSTtY6aZLvz9rjQmgZ2hcpJ.jpg\", \"tenants/2/noticias/carrossel/cUzy2FhNingxw9pBkRg930IfOSR2miP4J1NOO75K.jpg\", \"tenants/2/noticias/carrossel/zxOdfiUlYGTuxFLrbmA9OwjZaTWr5vj1qcOutBPs.jpg\", \"tenants/2/noticias/carrossel/xD2LPdQMWUXoxoGkXUco1d6kjvLMcZjmtVJP32mm.jpg\"]', 1, 1, '2026-03-07 16:00:00', 37, '2026-03-17 14:27:29', '2026-04-26 15:15:32', NULL),
(2, 2, 2, 1, 'Prefeito municipal de São Francisco do Maranhão assina  termo de adesão que garante a quinta participação do município nos Jogos Escolares', 'prefeito-municipal-de-sao-francisco-do-maranhao-assina-termo-de-adesao-que-garante-a-quinta-participacao-do-municipio-nos-jogos-escolares', '{\"time\":1774014333578,\"blocks\":[{\"id\":\"PeEtqUnTr_\",\"type\":\"paragraph\",\"data\":{\"text\":\"Na manhã desta sexta-feira, o prefeito municipal de São Francisco do Maranhão, Francisco do Posto, assinou o termo de adesão que garante a quinta participação do município nos Jogos Escolares Maranhenses (JEMs). O momento representa mais um passo importante no fortalecimento do esporte local e no incentivo à juventude franciscoense.\"}},{\"id\":\"mPpAFK9hnB\",\"type\":\"paragraph\",\"data\":{\"text\":\"Durante a assinatura, o prefeito esteve acompanhado do líder político Adelbarto Santos, do secretário de Esportes, Zé Borges, e do auxiliar técnico-administrativo da Secretaria de Esporte, professor Miguel, reforçando a união de esforços em prol do desenvolvimento esportivo no município.\"}},{\"id\":\"PxHPzhy0sn\",\"type\":\"image\",\"data\":{\"caption\":\"\",\"withBorder\":false,\"withBackground\":false,\"stretched\":false,\"file\":{\"url\":\"/backend/public/api/v1/public/media/tenants/2/editor_uploads/aq3nY0j5s4RWGkuIAe9rIiDCbIgokTyCnHV1Mbwm.jpg\"}}},{\"id\":\"QKCz99TLz1\",\"type\":\"paragraph\",\"data\":{\"text\":\"A adesão aos JEMs evidencia o compromisso da gestão com a valorização do esporte como ferramenta de inclusão social e formação cidadã. Mais do que competições, os jogos representam uma oportunidade de crescimento para os jovens, incentivando a disciplina, o respeito e o trabalho em equipe.\"}},{\"id\":\"BhDSahfVJw\",\"type\":\"paragraph\",\"data\":{\"text\":\"Em São Francisco do Maranhão, o esporte começa dentro das escolas e segue como um importante aliado da educação, contribuindo para a formação de cidadãos e para a construção de um futuro com mais oportunidades para todos.\"}}],\"version\":\"2.31.3\"}', 'Prefeito municipal de São Francisco do Maranhão, Francisco do Posto, assinou o termo de adesão que garante a quinta participação do município nos Jogos Escolar', 'tenants/2/noticias/qezjwp9v7o8j26MtA1O9X07R6JX1ttVX37ko4bec.jpg', NULL, NULL, NULL, 1, 1, '2026-03-20 10:30:00', 121, '2026-03-20 15:47:06', '2026-08-30 02:31:14', NULL),
(3, 2, 183, 1, 'ABERTURA DO CAMPEONATO FUTSAL MASTER', 'abertura-do-campeonato-futsal-master', '{\"time\":1775842094963,\"blocks\":[{\"id\":\"37y-V9YjOQ\",\"type\":\"paragraph\",\"data\":{\"text\":\"\\\"Nesta quinta feira 09 deu início ao grande Campeonato Futsal Master em comemoração ao aniversário de São Francisco do Maranhão.<br>Essa competição carrega tradição desde a gestão do ex-prefeito Adelbarto Santos, e agora o prefeito Francisco do Posto dá continuidade a esse legado.<br>Agradecemos a organização e a todos os atletas que fazem parte das equipes e mantêm vivo esse futsal. A Prefeitura, por meio da Secretaria Municipal de Esportes, está aqui para contribuir, dar apoio na organização e na premiação para todos.<br>Desejamos boa sorte a todas as equipes e atletas participantes. Que seja um grande campeonato!\\\"<br>#VivaoEsporte#FutsalMaster#GestãoFranciscodoPosto\"}}],\"version\":\"2.31.3\"}', NULL, NULL, NULL, NULL, '[\"tenants/2/noticias/carrossel/KJ6gskAcjJl5YyX5w2c674djEW8xZF0e3760ILzQ.jpg\", \"tenants/2/noticias/carrossel/0Cmo1ERDJX4RebZdOjQk334cQqdtEa1k1WFMTjqi.jpg\", \"tenants/2/noticias/carrossel/GW8FabQzq2ZN5FiOE3iQwQqHacS87531jcTB2R5U.jpg\", \"tenants/2/noticias/carrossel/Ihj6tLrZnLJlKJl0GjfBReWWEebL1jnxsexIp7GJ.jpg\", \"tenants/2/noticias/carrossel/WI1OHVhIPVxNoXBEi9qtkwTu9YnQk6JizkrlHD4h.jpg\", \"tenants/2/noticias/carrossel/FAXRxsJY98uIRq6Bg2PhMSSiQKBmDE6DGb0RwKy0.jpg\", \"tenants/2/noticias/carrossel/9GG6h1qscwzRK4SfEVyAnoutLgRdd58qGmBQBs0H.jpg\"]', 1, 0, '2026-04-10 14:29:48', 32, '2026-04-10 17:29:48', '2026-04-10 18:43:21', '2026-04-10 18:43:21'),
